import React, { useState, useEffect , useRef  } from 'react';
import './support.scss'
import { __ } from '@wordpress/i18n';
var plugin_url = nxtext_ajax_object.nxtex_url;


const SupportToggle = () => {

    if( nxtext_ajax_object?.dashData?.whiteLabel?.nxt_help_link == 'on' ){
        return false;
    }
    const supportUrl = !nxtext_ajax_object.pro ? 'https://wordpress.org/support/plugin/the-plus-addons-for-block-editor/' : 'https://store.posimyth.com/helpdesk/?utm_source=wpbackend&utm_medium=admin&utm_campaign=dashboardspage';
    const updatesUrl = 'https://roadmap.nexterwp.com/updates';
    const facebookUrl = 'https://www.facebook.com/groups/nexterwpcommunity';
    const featureRequestsUrl = 'https://roadmap.nexterwp.com/boards/feature-requests';
   // const reportBugUrl = 'https://roadmap.nexterwp.com/boards/feature-requests/';
    const youtubeUrl = 'https://www.youtube.com/c/POSIMYTHInnovations/?sub_confirmation=1';
    const twitterUrl = 'https://twitter.com/posimyth';
    const facebookPageUrl = 'https://www.facebook.com/nexterwp';
    const instagramUrl = 'https://www.instagram.com/posimyth';
    const blogUrl = 'https://nexterwp.com/blog/?utm_source=wpbackend&utm_medium=banner&utm_campaign=nextersettings';
    const affiliateUrl = 'https://store.posimyth.com/affiliate-program/?utm_source=wpbackend&utm_medium=admin&utm_campaign=links';

    const [isOpen, setIsOpen] = useState(false);
    const [showBackTop, setShowBackTop] = useState(false);
    const lastScrollTop = useRef(0);

    const animSvg = <svg xmlns="http://www.w3.org/2000/svg" width="24" height="14" fill="none" stroke="#727272"> <path className="arrow-one" d="M1 15l7-7-7-7" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/> <path className="arrow-two" d="M1 15l7-7-7-7" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/> <path className="arrow-three" d="M1 15l7-7-7-7" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/></svg>

    const handleToggle = () => {
        setIsOpen(!isOpen);
    };

    useEffect(() => {
        const handleScroll = () => {
            const currentScrollTop = window.pageYOffset || document.documentElement.scrollTop;
            
            if (currentScrollTop > 100 && currentScrollTop < lastScrollTop.current) {
                setShowBackTop(true);
            } else {
                setShowBackTop(false);
            }
            lastScrollTop.current = currentScrollTop <= 0 ? 0 : currentScrollTop;
        };
    
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if ( !event.target.closest('.nxt-dashsu-toggle') && !event.target.closest('.nxtblo-sup-top') && !event.target.closest('.nxtblo-sup-inner') ) {
                setIsOpen(false);
            }
        };

        const handleEscapeKey = (event) => {
            if (event.key === 'Escape') {
                setIsOpen(false);
            }
        };

        document.body.addEventListener('click', handleClickOutside);
        document.addEventListener('keydown', handleEscapeKey);

        return () => {
            document.body.removeEventListener('click', handleClickOutside);
            document.removeEventListener('keydown', handleEscapeKey);
        };
    }, []);


    return (
        <>
            { ( window.location.hash == '#/blocks' ) &&
                <div className={'nxt-back-top' + ( showBackTop ? ' visible' : '' )} onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' }) } >
                    <svg xmlns="http://www.w3.org/2000/svg" width="50" height="50" fill="none" viewBox="0 0 50 50"><rect width="50" height="50" fill="#1717CC" rx="25"/><path fill="#fff" d="M32.798 26.587a1.37 1.37 0 0 1-.972-.41l-6.773-6.774-6.774 6.774a1.368 1.368 0 0 1-1.93-1.861l7.732-7.745a1.368 1.368 0 0 1 1.935-.008l.008.008 7.732 7.745c.53.534.53 1.396 0 1.93a1.37 1.37 0 0 1-.958.341Z"/><path fill="#fff" d="M25.053 38a1.368 1.368 0 0 1-1.369-1.368V17.474a1.368 1.368 0 1 1 2.737 0v19.158c0 .755-.613 1.368-1.368 1.368ZM33.263 14.737h-16.42a1.368 1.368 0 1 1 0-2.737h16.42a1.368 1.368 0 1 1 0 2.737Z"/></svg>
                </div>
            }
           
            <div className="nxt-dashsu-toggle" onClick={handleToggle} title={__('Need Help?', 'nexter-extension')}> 
                { isOpen ?
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 512" width="30" height="30"><path d="M315.3 411.3c-6.253 6.253-16.37 6.253-22.63 0L160 278.6l-132.7 132.7c-6.253 6.253-16.37 6.253-22.63 0c-6.253-6.253-6.253-16.37 0-22.63L137.4 256L4.69 123.3c-6.253-6.253-6.253-16.37 0-22.63c6.253-6.253 16.37-6.253 22.63 0L160 233.4l132.7-132.7c6.253-6.253 16.37-6.253 22.63 0c6.253 6.253 6.253 16.37 0 22.63L182.6 256l132.7 132.7C321.6 394.9 321.6 405.1 315.3 411.3z"></path></svg>
                    :
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 384 512" width="30" height="30"><path d="M202.021 0C122.202 0 70.503 32.703 29.914 91.026c-7.363 10.58-5.093 25.086 5.178 32.874l43.138 32.709c10.373 7.865 25.132 6.026 33.253-4.148 25.049-31.381 43.63-49.449 82.757-49.449 30.764 0 68.816 19.799 68.816 49.631 0 22.552-18.617 34.134-48.993 51.164-35.423 19.86-82.299 44.576-82.299 106.405V320c0 13.255 10.745 24 24 24h72.471c13.255 0 24-10.745 24-24v-5.773c0-42.86 125.268-44.645 125.268-160.627C377.504 66.256 286.902 0 202.021 0zM192 373.459c-38.196 0-69.271 31.075-69.271 69.271 0 38.195 31.075 69.27 69.271 69.27s69.271-31.075 69.271-69.271-31.075-69.27-69.271-69.27z"/></svg>
                }
            </div>

            { isOpen &&
                <a href="https://posimyth.com/" className="nxtbloc-support-bottom" target="_blank" rel="noopener noreferrer"> Powered by POSIMYTH Innovations </a>
            }

            <div className={`nxt-dashsu-content ${isOpen ? 'active' : ''}`} key={isOpen ? 'open' : 'closed'}>
                <div className="nxtblo-sup-top">
                    <h3 className="nxtext_primary_heading"> { __('Quick Support', 'nexter-extension') }</h3>
                    <span className="nxtblo-sup-label">
                        { !nxtext_ajax_object.pro ? __('FREE VERSION', 'nexter-extension')  : __('PRO VERSION', 'nexter-extension') }
                    </span>
                </div>
                <div className="nxtblo-sup-inner">
                    <div className="nxtblo-sup-wrap">
                        <div className="nxtblo-sup-list">
                            <a href={supportUrl} target="_blank" className="nxtblo-sup-link" rel="noopener noreferrer">
                                <span className="nxtblo-title-wrap">
                                    {!nxtext_ajax_object.pro ? __('Get Free Support', 'nexter-extension') : __('Get Premium Support', 'nexter-extension') }
                                </span>
                                {animSvg}
                            </a>
                        </div>
                        <div className="nxtblo-sup-list">
                            <a href={updatesUrl} target="_blank" className="nxtblo-sup-link" rel="noopener noreferrer">
                                <span className="nxtblo-title-wrap">{ __('Whats New?', 'nexter-extension') } </span>
                                {animSvg}
                            </a>
                        </div>
                        <div className="nxtblo-sup-list">
                            <a href={facebookUrl} target="_blank" className="nxtblo-sup-link" rel="noopener noreferrer">
                                <span className="nxtblo-title-wrap"> { __('Join Facebook Community', 'nexter-extension') } </span>
                                {animSvg}
                            </a>
                        </div>
                        <div className="nxtblo-sup-list">
                            <a href={featureRequestsUrl} target="_blank" className="nxtblo-sup-link" rel="noopener noreferrer">
                                <span className="nxtblo-title-wrap"> { __('Suggest New Features', 'nexter-extension') } </span>
                                {animSvg}
                            </a>
                        </div>
                        {/* <div className="nxtblo-sup-list">
                            <a href={reportBugUrl} target="_blank" className="nxtblo-sup-link" rel="noopener noreferrer">
                                <span className="nxtblo-title-wrap">  { __('Report Bug', 'nexter-extension') } </span>
                                {animSvg}
                            </a>
                        </div> */}
                        <div className="nxtblo-sup-list">
                            <a href={'https://nexterwp.com/chat?utm_source=wpbackend&utm_medium=banner&utm_campaign=nextersettings'} target="_blank" className="nxtblo-sup-link" rel="noopener noreferrer">
                                <span className="nxtblo-title-wrap">{ __('AI Chat', 'nexter-extension') } </span>
                                {animSvg}
                            </a>
                        </div>
                    </div>
                    {/* <div className='nxtblo-sale'> <img src={plugin_url + 'assets/images/sale.jpg'} draggable={false} /> </div> */}
                    <div className="nxtblo-panel-row">
                        <a href={youtubeUrl} className="nxtblo-panel-col nxtblo-social-link" title="Youtube" target="_blank" rel="noopener noreferrer">
                            <span>
                                <svg xmlns="http://www.w3.org/2000/svg" width="27" height="27" fill="none" viewBox="0 0 27 27"><circle cx="13.5" cy="13.5" r="13.5" fill="#E9EBF5"/><g clipPath="url(#a)"><path fill="#1717CC" d="M21.02 10.226a1.972 1.972 0 0 0-1.387-1.397c-1.224-.33-6.132-.33-6.132-.33s-4.909 0-6.133.33a1.972 1.972 0 0 0-1.388 1.397c-.328 1.232-.328 3.802-.328 3.802s0 2.57.328 3.803c.18.68.713 1.193 1.388 1.374 1.224.33 6.133.33 6.133.33s4.908 0 6.132-.33a1.943 1.943 0 0 0 1.388-1.374c.328-1.232.328-3.803.328-3.803s0-2.57-.328-3.802Zm-9.125 6.136v-4.667l4.103 2.333-4.103 2.334Z"/></g><defs><clipPath id="a"><path fill="#fff" d="M5.625 6.66h15.75v14.715H5.625z"/></clipPath></defs></svg>
                            </span>
                        </a>
                        <a href={twitterUrl} className="nxtblo-panel-col nxtblo-social-link" title="Twitter" target="_blank" rel="noopener noreferrer">
                            <span>
                                <svg xmlns="http://www.w3.org/2000/svg" width="27" height="27" fill="none" viewBox="0 0 27 27"><circle cx="13.5" cy="13.5" r="13.5" fill="#E9EBF5"/><g clipPath="url(#a)"><path fill="#1717CC" d="m15.342 12.669 5.737-6.67h-1.36l-4.981 5.792L10.759 6h-4.59l6.018 8.756L6.17 21.75h1.36l5.26-6.115 4.202 6.115h4.59l-6.24-9.081Zm-1.862 2.165-.61-.872-4.85-6.939h2.088l3.914 5.6.61.872 5.088 7.278h-2.088l-4.152-5.94Z"/></g><defs><clipPath id="a"><path fill="#fff" d="M6 6h15.75v15.75H6z"/></clipPath></defs></svg>
                            </span>
                        </a>
                        <a href={facebookPageUrl} className="nxtblo-panel-col nxtblo-social-link" title="Facebook" target="_blank" rel="noopener noreferrer">
                            <span>
                                <svg xmlns="http://www.w3.org/2000/svg" width="27" height="27" fill="none" viewBox="0 0 27 27"><circle cx="13.5" cy="13.5" r="13.5" fill="#E9EBF5"/><g clipPath="url(#a)"><path fill="#1717CC" d="m17.164 14.484.437-2.85h-2.735v-1.85c0-.78.382-1.54 1.607-1.54h1.244V5.818s-1.129-.193-2.207-.193c-2.253 0-3.725 1.365-3.725 3.837v2.172H9.28v2.85h2.504v6.891h3.081v-6.89h2.298Z"/></g><defs><clipPath id="a"><path fill="#fff" d="M5.625 5.625h15.75v15.75H5.625z"/></clipPath></defs></svg>
                            </span>
                        </a>
                        <a href={instagramUrl} className="nxtblo-panel-col nxtblo-social-link" title="Instagram" target="_blank" rel="noopener noreferrer">
                            <span>
                                <svg xmlns="http://www.w3.org/2000/svg" width="27" height="27" fill="none" viewBox="0 0 27 27"><circle cx="13.5" cy="13.5" r="13.5" fill="#E9EBF5"/><path fill="#1717CC" d="M13.503 9.962a3.529 3.529 0 0 0-3.534 3.535 3.529 3.529 0 0 0 3.534 3.535 3.529 3.529 0 0 0 3.535-3.535 3.529 3.529 0 0 0-3.535-3.535Zm0 5.833a2.302 2.302 0 0 1-2.297-2.298 2.3 2.3 0 0 1 2.297-2.298 2.3 2.3 0 0 1 2.298 2.298 2.302 2.302 0 0 1-2.298 2.298Zm4.504-5.977c0 .458-.37.824-.825.824a.824.824 0 1 1 .824-.824Zm2.34.837c-.051-1.105-.304-2.083-1.113-2.889-.806-.806-1.784-1.058-2.888-1.114-1.138-.064-4.55-.064-5.688 0-1.101.053-2.08.305-2.889 1.11-.809.807-1.058 1.785-1.113 2.89-.065 1.138-.065 4.55 0 5.687.052 1.105.304 2.083 1.113 2.889.81.806 1.785 1.058 2.889 1.113 1.138.065 4.55.065 5.688 0 1.104-.052 2.082-.304 2.888-1.113.806-.806 1.058-1.784 1.114-2.889.065-1.138.065-4.546 0-5.684Zm-1.47 6.906a2.326 2.326 0 0 1-1.31 1.31c-.907.36-3.06.277-4.064.277-1.002 0-3.159.08-4.063-.277a2.326 2.326 0 0 1-1.31-1.31c-.36-.908-.278-3.061-.278-4.064 0-1.003-.08-3.16.277-4.064a2.326 2.326 0 0 1 1.31-1.31c.908-.36 3.062-.277 4.064-.277 1.003 0 3.16-.08 4.064.277.603.24 1.067.704 1.31 1.31.36.908.277 3.061.277 4.064 0 1.003.083 3.16-.276 4.064Z"/></svg>
                            </span>
                        </a>
                        <a href={blogUrl} className="nxtblo-panel-col nxtblo-social-link" title="RSS" target="_blank" rel="noopener noreferrer">
                            <span>
                                <svg xmlns="http://www.w3.org/2000/svg" width="27" height="27" fill="none" viewBox="0 0 27 27"><circle cx="13.5" cy="13.5" r="13.5" fill="#E9EBF5"/><g clipPath="url(#a)"><path fill="#1717CC" d="M7.687 11.16a.706.706 0 0 0-.748.652.703.703 0 0 0 .656.748c3.519.23 6.612 3.301 6.844 6.843.025.375.332.66.675.66l.047-.002a.703.703 0 0 0 .656-.747c-.249-4.223-3.908-7.882-8.13-8.155Zm.188-4.223a.937.937 0 1 0 0 1.875c5.687 0 10.313 4.626 10.313 10.313a.937.937 0 1 0 1.875 0c0-6.72-5.467-12.188-12.188-12.188Zm.911 9.372c-1.01 0-1.848.841-1.848 1.878 0 1.038.838 1.875 1.848 1.875 1.01 0 1.878-.838 1.878-1.875a1.862 1.862 0 0 0-1.878-1.878Z"/></g><defs><clipPath id="a"><path fill="#fff" d="M6 6h15v15H6z"/></clipPath></defs></svg>
                            </span>
                        </a>
                        <a href={affiliateUrl} className="nxtblo-panel-col nxtblo-social-link" title="Affiliate" target="_blank" rel="noopener noreferrer">
                            <span>
                                <svg xmlns="http://www.w3.org/2000/svg" width="27" height="27" fill="none" viewBox="0 0 27 27"><circle cx="13.5" cy="13.5" r="13.5" fill="#E9EBF5"/><path fill="#1717CC" d="M13.994 18.135a5.613 5.613 0 0 1-1.633-.22 3.999 3.999 0 0 1-1.386-.804 1.025 1.025 0 0 1-.26-.324.805.805 0 0 1-.09-.363c0-.199.07-.371.207-.518a.719.719 0 0 1 .545-.234c.164 0 .31.052.44.156.329.268.652.47.972.61.328.137.73.206 1.205.206.32 0 .614-.047.882-.142.267-.104.483-.238.648-.402a.826.826 0 0 0 .246-.583.98.98 0 0 0-.234-.66c-.155-.182-.393-.333-.712-.454-.32-.13-.726-.23-1.218-.299a5.687 5.687 0 0 1-1.232-.31 3.126 3.126 0 0 1-.894-.545 2.268 2.268 0 0 1-.531-.777 2.7 2.7 0 0 1-.181-1.011c0-.562.142-1.041.427-1.439.294-.397.687-.7 1.18-.907a4.167 4.167 0 0 1 1.632-.31c.562 0 1.08.086 1.555.258.484.165.877.376 1.18.635.25.2.375.428.375.687 0 .19-.073.363-.22.519a.69.69 0 0 1-.518.233.568.568 0 0 1-.35-.117 2.21 2.21 0 0 0-.557-.337 4.183 4.183 0 0 0-.739-.272 2.762 2.762 0 0 0-1.672.026c-.25.095-.44.225-.57.389a.894.894 0 0 0-.194.57c0 .26.073.475.22.648.155.164.376.298.66.402a8.33 8.33 0 0 0 1.025.259c.518.095.972.207 1.36.337.398.13.726.298.985.505.26.199.454.454.583.765.13.302.195.674.195 1.114 0 .562-.156 1.046-.467 1.452a2.98 2.98 0 0 1-1.23.933 4.08 4.08 0 0 1-1.634.324Zm.933.7c0 .224-.077.41-.233.557a.734.734 0 0 1-.557.233.719.719 0 0 1-.544-.233.755.755 0 0 1-.22-.558V8.416a.776.776 0 0 1 .79-.79c.224-.001.406.077.544.232.147.147.22.333.22.558v10.418Z"/></svg>
                            </span>
                        </a>
                        
                    </div>
                    {nxtext_ajax_object.dashData.wpVersion && nxtext_ajax_object.dashData.pluginVer && 
                        <div className="nxtblo-panel-row" style={{ justifyContent: 'center' , columnGap: '10px' }}> 
                            <span className="nxt-version-info"> { __('WordPress Version: ', 'nexter-extension') + nxtext_ajax_object.dashData.wpVersion } </span><span>|</span>
                            <span className="nxt-version-info"> { __('Plugin Version: ', 'nexter-extension') + nxtext_ajax_object.dashData.pluginVer } </span>
                        </div>
                    }
                </div>
                
            </div>
        </>
    )
}

export default SupportToggle;