class Nexter_Note extends Component {
    constructor(props) {
        super(props)
    }
	
    render() {
        const { label, separator, color, description } = this.props
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';
		const styleColor = (color!='') ? { color: color } : '';
        return (
			<div className={'nexter-field nexter-field-note ' + (sep ? sep : '')} >
				<span style={styleColor}>{ label ? label : __('Note : ', 'nexter-extension') }</span>
				{ description!='' ? <span dangerouslySetInnerHTML={{ __html: description }}></span> : '' }
			</div>
        )
    }
}

class Nexter_Text extends Component {
    constructor(props) {
        super(props)
        this.state = { current: '' }
    }
    
	setSettings(val) {
        const { value, onChange } = this.props
		let final = val;
        onChange(final)
        this.setState({ current: final })
    }
	
    render() {
        const { label, value, type, min, max, step, help, className, inlineblock, separator, placeholder  , diff  } = this.props
        
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';
		
		const typeval = (type!='' && type!=undefined) ? type : 'text';
		
		const inline_content = inlineblock==false ? '' : 'nexter-inline-block nexter-d-flex';
		const inline_content_text = inlineblock==false ? 'nexter-mt-5' : '';
		const placeholder_text = (placeholder) ? placeholder : '';
		
        return (
			<div className={"nexter-field-text nexter-field " + inline_content + ' '+ (sep ? sep : '') }>
               
			   	{label && <label  className={ nexterfieldChange( diff , value ) } >{label}
					{/* <Nexter_Help>{help}</Nexter_Help> */}
					</label>}
				
				<div className={"nexter-field-child "+ inline_content_text }>
						<TextControl
							label={""}
							type={typeval}
							min={min || 0}
							step={step || 1}
							max={max || 10000}
							value={ value }
							className={className}
							placeholder={placeholder_text}
							onChange={ ( val ) => this.setSettings( val ) }
						/>
                </div>
            </div>
        )
    }
}

class Nexter_RadioAdvanced extends Component {

    constructor(props) {
        super(props)
        this.state = { current: this._filterValue() }
    }

    _filterValue() {
        const { value,responsive, device } = this.props
        return value ? (responsive ? (value[device] || '') : value) : '';
    }

    setSettings(val){

        const { value,responsive,responsiveGroup,onChange, name, device } = this.props
        var final = responsive || responsiveGroup ? Object.assign({}, value, nexter_defineProperty({}, device, val)) : val;

        onChange( final )
        this.setState({ current: final })
    }

    render() {
        const { value, responsive,device,onDeviceChange ,label, options, separator , inlineblock , diff } = this.props;
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';
        const inlinecontent = inlineblock==true ? ' nexter-block-inline' : '';
        return (
            <div className={"nexter-field nexter-field-radio-advanced nexter-d-flex nexter-align-center " + (sep ? sep : '') + inlinecontent }>
                { label &&
                    <span>{label}</span>
                }
                <div className={`nexter-field-button-list${ inlineblock==true ? '' : ' nexter-ml-auto' }`}>
                    {
                        options.map((data, index) => {
                            return (
                                <Tooltip text={ data.title || data.value } key={index.toString()}>
                                    <button className={(this._filterValue() == data.value ? 'active' : '') + ' nexter-button'} key={index} onClick={ () => this.setSettings( this._filterValue() == data.value ? '' : data.value )} >
                                        {data.icon ? (<i className={ data.icon } />)
                                        : data.svg ? (<span className='nexter-option-svg'>{data.svg}</span>)
                                        : data.label}
                                    </button>
                                </Tooltip>
                            )
                        })
                    }
                </div>
            </div>
        )
    }
}

class Nexter_Color extends Component {
    constructor(props) {
        super(props)
		this.state = { Status : false }
	}
	
    render() {
        const { label, className, value, disablePalette, disableAlpha, disableClear, disableGlobal, onChange, separator, help , diff } = this.props
		const { Status } =this.state

		let colorSelected = (value && value != '') ? 'nxt-remove-bg-img' : '';
		
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';
		
        return (
            <div className={`nexter-field nexter-field-color nexter-d-flex nexter-inline-block ${className ? className : ''} ${sep} ${ !disableGlobal ? 'nexter-colglo' : '' }`}>
                {label && <label className={"nexter-mb-0" + nexterfieldChange( diff , value )}>{label}{/* <Nexter_Help>{help}</Nexter_Help> */}</label>}
                <div className={"nexter-flex"}>
				{(value != '' && !disableClear) &&
                    <div className="nexter-reset-color">
						<Tooltip text={__('Clear', 'nexter-extension')}>
                            <span className="nexter-border-clear nexter-flex" onClick={() => {onChange(''); this.setState({Status: false }); } } role="button">
								{Nexter_Icons.ClearIcon}
							</span>
						</Tooltip>
                    </div>
                }
				<Dropdown
                    popoverProps={ { placement: 'top-start' } }
                    className={"nexter-ml-auto"}
					contentClassName="nexter-popover-style"
                    renderToggle={({ isOpen, onToggle }) => (
                        <Fragment>
                            <span className="nexter-color-picker-container">
                                <button className={"nexter-color-picker "+colorSelected} style={{backgroundColor: value || '',borderColor: value || ''}} isPrimary onClick={onToggle} aria-expanded={isOpen} />
                            </span>
                        </Fragment>
                    )}
                    renderContent={() => (
                        <span>
                            <ColorPicker color={value || ''}
                                onChangeComplete={val => {
                                    if (val.rgb) { onChange(val.rgb.a != 1 ? 'rgba(' + val.rgb.r + ',' + val.rgb.g + ',' + val.rgb.b + ',' + val.rgb.a + ')' : val.hex) }
									this.setState({Status: false });
                                }}
                                disableAlpha={disableAlpha ? disableAlpha : false} />
                        </span>
                    )}
                />
                </div>
            </div>
        )
    }
}

class Nexter_Media extends Component {

	setSettings( media ) {
		const { multiple, onChange,value} = this.props
		if( multiple ){
			let media_list = [];
			media.forEach( single => {
				if ( single && single.url ){
					media_list.push( {url: single.url, id: single.id, title: media.title , alt: media.alt} );
				}
			});
			onChange( value ? value.concat(media_list) : media_list );
		}else{
			if ( media && media.url ) {
				onChange({url: media.url, id: media.id, title: media.title, alt: media.alt , sizes : media.sizes , caption : media.caption});
			}
		}
	}

	removeImage( id ){
		const { multiple, onChange } = this.props
		if( multiple ){
			let value = (this.props.value).slice()
			value.splice(id, 1)
			onChange( value )
		}else{
			onChange({})
		}
	}

	isUrl(url){
		if( ['wbm','jpg','jpeg','gif','png', 'svg','webp'].indexOf( url.split('.').pop().toLowerCase() ) != -1 ){
			return url;
		}else if(['mp4','m4v','mov','wmv','avi', 'mpg', 'ogv', '3gp'].indexOf( url.split('.').pop().toLowerCase() ) != -1){
			return nxtext_ajax_object.dashData.pluginpath + 'assets/images/nexter-ext-video-placeholder.jpg';
		}else{
			return nxtext_ajax_object.dashData.pluginpath + 'assets/images/nexter-ext-placeholder.jpg';
		}
	}
	
	isVideoUrl(url){
		if( ['mp4','m4v','mov','wmv','avi', 'mpg', 'ogv', '3gp'].indexOf( url.split('.').pop().toLowerCase() ) != -1 ){
			return true;
		}else{
			return false;
		}
	}
	

	render() {
		const { type,multiple,value,panel,separator, help , diff } = this.props;
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';
		return (
			<div className={'nexter-media ' + (sep ? sep : '')}>
				{ this.props.label &&
					<label className={ nexterfieldChange( diff , value , '' , '' , '' , '' , true ) } >{this.props.label}{/* <Nexter_Help>{help}</Nexter_Help> */}</label>
				}
				<MediaUpload
					onSelect={ val => this.setSettings(val) }
					allowedTypes={ type || ['image'] }
					multiple={ multiple || false }
					value={ value }
					render={({ open }) => (
						<div className={"nexter-single-img "+(multiple ? 'nexter-multi-img' : '')}>
							<div>
								{ multiple ?
									<div>
										{ ( value.length > 0 ) &&
											value.map( (v,index) => {
												return(
													<span className="nexter-media-image-parent" key={index.toString()} >
														<img src={this.isUrl(v.url)} alt={__('image', 'nexter-extension')}/>
														{ (this.isVideoUrl(v.url) && type.includes("video") && v.title) &&
															<span className={'nexter-media-video-title'}>{v.title || ''}</span>
														}
														{ panel &&
															<div className="nexter-media-actions nexter-field-button-list">
																<Tooltip text={__('Delete', 'nexter-extension')} delay={0} placement={'top'}>
																	<button className="nexter-button nexter-media-remove" aria-label={__('Remove', 'nexter-extension')} onClick={ () => this.removeImage(value.id) } role="button">
																		{ Nexter_Icons.mediaDelete }
																	</button>
																</Tooltip>
															</div>
														}
													</span>
												)
											} )
										}
										<div onClick={open} className={"nexter-placeholder-image"}>
											<Tooltip text={__( 'Insert', 'nexter-extension' )} delay={0} >
												<span className={`nexter-field-border-type nexter-d-flex nexter-align-center`} >
													<svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><g clipPath="url(#clip0_523_6822)"><path d="M7.99979 5.33341V10.6667M5.33403 7.99994H10.6674M14.957 7.99998C14.957 11.842 11.8424 14.9565 8.00047 14.9565C4.15849 14.9565 1.04395 11.842 1.04395 7.99998C1.04395 4.158 4.15849 1.04346 8.00047 1.04346C11.8424 1.04346 14.957 4.158 14.957 7.99998Z" stroke="black" strokeWidth="0.5" strokeLinecap="round" strokeLinejoin="round"/></g><defs><clipPath id="clip0_523_6822"><rect width="16" height="16" fill="white"/></clipPath></defs></svg>
												</span>
											</Tooltip>
										</div>
									</div>
									:
									( ( value && value.url ) ? 
										<span className="nexter-media-image-parent"> 
											<img src={this.isUrl(value.url)} alt={__('image', 'nexter-extension')}/>
											{(this.isVideoUrl(value.url) && type.includes("video") && value.title) &&
												<span className={'nexter-media-video-title'}>{value.title || ''}</span>
											}
											{ panel &&
												<div className="nexter-media-actions nexter-field-button-list">
													<Tooltip text={__('Delete', 'nexter-extension')} delay={0} placement={'top'}>
														<button className="nexter-button nexter-media-remove" aria-label={__('Remove', 'nexter-extension')} onClick={ () => this.removeImage(value.id) } role="button">
															{ Nexter_Icons.mediaDelete }
														</button>
													</Tooltip>
												</div>
											}
										</span>
										:
										<div onClick={open} className={"nexter-placeholder-image"}>
											<Tooltip text={__( 'Insert', 'nexter-extension' )} delay={0} >
												<span className={`nexter-field-border-type nexter-d-flex nexter-align-center`} >
													<svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><g clipPath="url(#clip0_523_6822)"><path d="M7.99979 5.33341V10.6667M5.33403 7.99994H10.6674M14.957 7.99998C14.957 11.842 11.8424 14.9565 8.00047 14.9565C4.15849 14.9565 1.04395 11.842 1.04395 7.99998C1.04395 4.158 4.15849 1.04346 8.00047 1.04346C11.8424 1.04346 14.957 4.158 14.957 7.99998Z" stroke="black" strokeWidth="0.5" strokeLinecap="round" strokeLinejoin="round"/></g><defs><clipPath id="clip0_523_6822"><rect width="16" height="16" fill="white"/></clipPath></defs></svg>
												</span>
											</Tooltip>
										</div>
									)
								}
							</div>
							<div className="nexter-img-bottom" onClick={open} > { 
								(value && value.url) ? 
									(type.includes("video") ? __( 'Replace Video', 'nexter-extension' ) :
									type.includes("image/svg+xml") ? __( 'Replace SVG', 'nexter-extension' ) :
									__( 'Replace Image', 'nexter-extension' )) : 
								(type.includes("video") ? __( 'Upload Video', 'nexter-extension' ) :
								type.includes("image/svg+xml") ? __( 'Upload SVG', 'nexter-extension' ) :
								__( 'Upload Image', 'nexter-extension' ))
								} </div>
						</div>
					)}
				/>
			</div>
		);
	}
}

class Nexter_Select extends Component {
    constructor(props) {
        super(props)
        this.state = { current: '', device: 'md' }
    }
    _filterValue() {
        const { value, responsive, device } = this.props
		return value ? (responsive ? (value[device] || '') : value) : '';
    }
    setSettings(val) {
        const { value, onChange, responsive, device } = this.props
		let final = responsive ? Object.assign({}, value, nexter_defineProperty({}, device, val)) : val;
        onChange(final)
        this.setState({ current: final })
    }
	
    render() {
        const { label, responsive, device, onDeviceChange, separator, inlineblock, help , diff } = this.props
        const direction = this.props.direction == 'left' ? '  direction-left' : this.props.direction == 'right' ? '  direction-right' : '';
		let responsiveDevice = responsive ? device ? device : this.state.device : window.nexterDevice
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';
		const inlinecontent = inlineblock==false ? '' : 'nexter-inline-block';
        return (
		<div className={"nexter-field-select nexter-field nexter-d-flex " + (this.props.responsive ? 'nexter-responsive' : '') +' '+ (sep ? sep : '') +' '+ inlinecontent}>
               
                {label && <label className={ "nexter-sele-lbl " +(inlineblock==false ? "nexter-mb-5" : '') + nexterfieldChange( diff ,  this.props.value , responsive , device , '', '', '', true) }>{label}{/* <Nexter_Help>{help}</Nexter_Help> */}</label>}
                {responsive && 
					<div className={'flex-device-wrap' + (inlineblock==false ? " nexter-mb-5" : '')}>
						{ (device) &&
							<Nexter_Device device={responsiveDevice} commonResponsiveDevice={device} className="nexter-ml-10" onChange={(val) => { onDeviceChange(val) }} />
						}{ (device =='') &&
							<Nexter_Device className="nexter-ml-10" onChange={(val) => { this.setState({ current: val }) }} />
						}
					</div>
				}
                <div className="nexter-field-child">
                    <div className={"nexter-popup-select " + direction} ref={node => this.node = node}>
                        {(this.props.clear && this._filterValue() != '') &&
                            <span className={'nexter-clear'} onClick={() => this.setSettings("")}><i className="fas fa-times" /></span>
                        }
                        <select value={this._filterValue()} onChange={(e) => this.setSettings(e.target.value)}>
                            {(this.props.noValue || this.props.clear) &&
                                <option value="">{this.props.noValue || this.props.initial ? this.props.initial : __('Select', 'nexter-extension')}</option>
                            }
							{ this.props.options.map((item, index) => {
								if(typeof item[0] === 'object' && item[0].label && item[0].options){
									return (<optgroup key={index.toString()} label={(item[0].label) ? item[0].label : ''}>
										{ item[0].options.map((subitem,subindex) => 
											<option value={Array.isArray(subitem) ? subitem[0] : subitem}  key={subindex.toString()} onClick={() => this.setSettings(Array.isArray(subitem) ? subitem[0] : subitem)}>{Array.isArray(subitem) ? subitem[1] : subitem}</option>
										)}
									</optgroup>)
								}else{
									return <option value={Array.isArray(item) ? item[0] : item}  key={index.toString()} onClick={() => this.setSettings(Array.isArray(item) ? item[0] : item)}>{Array.isArray(item) ? item[1] : item}</option>
								}
							}) 
							}
                        </select>
                    </div>
                </div>
            </div>
        )
    }
}

class Nexter_Gradient extends Component {

    constructor(props) {
        super(props)
        this.state = {Status : false }
    }
	
	componentWillMount(){
        const { value } = this.props
		this.props.onChange(value);
    }

    render() {
        const { value, separator } = this.props
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';

        const {Status} = this.state
		
        return (
            <div className={"nexter-gradient nexter-field inline " + (sep ? sep : '')}>
                { !Status &&
                    <GradientPicker 
                        gradients={
                            this.props.gradients !== undefined ? this.props.gradient : []
                        }
                        value={value === '' ? null : value || null}
                        clearable={false}
                        disableCustomGradients={false}
                        onChange={val => this.props.onChange(val)}
                    />
                }
            </div>
        )
    }
}

