		data = Object.assign({}, responsive ? value[device] || {} : value, data)
		
        const final = Object.assign({}, value, responsive ? nexter_defineProperty({}, device, data) : data)
        
		final.unit = data.unit || 'px'
        onChange(final)
        this.setState({ current: final })
