class Nexter_Range extends Component {
    constructor(props) {
        super(props)
        this.state = { current: '', device: 'md' }
    }
    handleSetDeviceType = (deviceType) => {
        this.setState({ deviceType });
    };

    _filterValue(type) {
        const { value, responsive, device } = this.props
        if (type == 'unit') {
            return value ? (value.unit || 'px') : 'px'
			} else {
            return value ? (responsive ? (value[device] || '') : value) : ''
        }
    }

    setSettings(val, type) {
        const { value, onChange, responsive, min, max, unit, device } = this.props
        
        let final = {}
        if (unit && (value && !value.hasOwnProperty('unit'))) { final = Object.assign({}, value, nexter_defineProperty({}, 'unit', 'px')) }
        if ((type === 'unit' || type === 'unitsm' || type === 'unitxs') && responsive) {
            final = Object.assign({}, value, nexter_defineProperty({}, type, val))
        }else {
            final = (responsive) ? Object.assign({}, value, final, nexter_defineProperty({}, device, val)) : val
            final = (final!="" && min) ? (final < min ? min : final) : (final < 0 ? 0 : final)
            final = max ? (final > max ? max : final) : (final > 1000 ? 1000 : final)
        }

        onChange(final)
        this.setState({ current: final })
    }

    _minMax(type) {
        let unit = this._filterValue('unit')
        if(type=='max' && unit=='%' ){
            return 100;
        }
        return (this.props[type] && this.props[type] != 0) ? ((unit == 'rem' || unit == 'em') ? Math.round(this.props[type] / 16) : this.props[type]) : 0
    }

    _steps() {
        let unit = this._filterValue('unit')
        if(unit == '%' ){
            return 0.5;
        }
        return (unit == 'rem' || unit == 'em') ? .1 : (this.props.step || 1)
    }

    updateDevice(updatedDevice) {
        let { value, onChange, device } = this.props
        if (typeof device !== 'undefined') {
            onChange({ ...value, device: updatedDevice })
        }
        this.setState({ device: updatedDevice })
    }

    render() {
        const { unit, label, responsive, device, onDeviceChange, separator, help , deviceAlign , cssFilter , value , diff} = this.props
        let responsiveDevice = responsive ? device ? device : this.state.device : window.nexterDevice
		const sep = (separator!='' && separator=='before') ? 'nexter-separator-before' : (separator!='' && separator=='after') ? 'nexter-separator-after' : '';

        let UnitResponsive = 'unit';
        let UnitValue = ( this.props.value && this.props.value.unit) ? this.props.value.unit : '';
        if(responsive && device){
            if(device != 'md'){
                UnitResponsive = 'unit'+device;
                UnitValue = (this.props.value) ? (this.props.value[UnitResponsive] || UnitValue) : UnitValue
            }
        }
        let updatedUnit;
        if(unit){
            if ( typeof unit === 'object') {
                updatedUnit = unit;
            } else {
                updatedUnit = ['px', 'em', '%'];
            }    
        }
       
        let uid = 'id-' + Date.now() + '-' + Math.floor(Math.random() * 10000);
       
        if( !cssFilter ){
            var percentage = (this._filterValue() - this._minMax('min')) / (this._minMax('max') - this._minMax('min')) * 100,
            trackColor = '.nexter-input-range.'+uid+' input[type=range]::-webkit-slider-runnable-track{ background: linear-gradient( to right, #162D9E '+percentage+'%, #E7E7F6 '+(percentage)+'% ) !important;} .nexter-input-range.'+uid+' input[type=range]::-moz-range-track{ background: linear-gradient( to right, #162D9E '+percentage+'%, #E7E7F6 '+(percentage)+'% ) !important;} ';
        }

        return (
		<div className={'nexter-field-range nexter-field ' + (responsive ? 'nexter-responsive' : '') +' '+ (sep ? sep : '')}>
                {(label || unit || responsive) &&
                    <div className="nexter-d-flex nexter-align-center">
                        {label &&
                            <label className={ nexterfieldChange( diff , value , responsive , device , false , true  ) } htmlFor={'input'}>
                                {label}
                            </label>
                        }

                        {responsive && <Nexter_Device align={deviceAlign || ''} device={responsiveDevice} commonResponsiveDevice={device} setDeviceType={this.handleSetDeviceType} className="nexter-ml-10" onChange={(val) => { device && onDeviceChange ? onDeviceChange(val) : this.updateDevice(val) }} />}

                        {/* <Nexter_Help>{help}</Nexter_Help> */}
                        { ( updatedUnit && updatedUnit != undefined ) &&
                            
                            <div className="nexter-unit-btn-group nexter-ml-auto">
                                {/* {(typeof unit == 'object' ? unit : ['px', 'em', '%']).map((value,index) => (
                                    <button className={(this.props.value && value == UnitValue) ? 'active' : ''}
										key={index.toString()} 
                                        onClick={() => {
                                            this.setSettings(value, UnitResponsive)
                                        }}
                                    >{value}</button>
                                ))} */}
                                <Nexter_Select value={ (this.props.value) ? UnitValue : '' } options={ updatedUnit } onChange={ (val)=>  this.setSettings(val, UnitResponsive) } inlineblock={ false } />
                            </div>
                        }
                    </div>
                }

                <div className="nxp-field-child">
                    <div className={"nexter-input-range "+((this.props.value && this.props.value.unit=='c') ? 'text-d-block ' : '')+ uid}>
                        {(this.props.value && this.props.value.unit=='c') ?
                            <Fragment><Nexter_Text
                                label={''}
                                value={ this._filterValue() }
                                placeholder={'clamp(1.8rem, 1.5rem + 0.8vw, 2rem)'}
                                onChange={ val => this.setSettings(val, 'range') }
                                inlineblock={false}
                            />
                            <Nexter_Note label={__('Tip : ', 'nexter-extension')} description={'<a href="https://clamp.font-size.app/" target="_blank" rel="noopener noreferrer">Generate Clamp Code</a>'} />
                            </Fragment>  
                        :
                        <Fragment>
                            <input
                                type="range"
                                min={this._minMax('min')}
                                max={this._minMax('max')}
                                value={this._filterValue()}
                                step={this._steps()}
                                onChange={e => this.setSettings(this._filterValue() == e.target.value ? '' : e.target.value, 'range')}
                            />

                            <input type="number" step={this._steps()} onChange={v => this.setSettings(v.target.value, 'range')} value={this._filterValue() + (this.props.suffix ? this.props.suffix : '')} {...(this.props.suffix && { disabled: true })} />
                        </Fragment>
                    }
                    {( this._filterValue() && trackColor )&&
                        <style>{ trackColor }</style>
                    }
                    </div>
                </div>
            </div>
        )
    }
}

