// Fetch Data From AJAX
export const nxtdash_fetch_api = async (args) => {
    if (args) {        
        try {
            const response = await fetch(nxtext_ajax_object.ajax_url, {
                method: 'POST',
                body: args
            });

            if (!response.ok) {
                throw new Error(`HTTP error! Status: ${response.status}`);
            }

            const data = await response.json();
            return data;
        } catch (error) {
            return error.message;
        }
    } else {
        return false;
    }
}

// Form Append Data
export const appendFormData = (form, data) => {
    for (const key in data) {
        if (data.hasOwnProperty(key)) {
            form.append(key, data[key]);
        }
    }
};

export const nxtdash_install_theme = async (e, args, setNexterThemeIntall) => {
    e.target.innerHTML = '<span class="nxtext-loading-circle"></span>';
	try {
		const response = await nxtdash_fetch_api(args),
        data = await response;
    
        if (data) {            
            setNexterThemeIntall(true)
            e.target.innerHTML = 'Installed';
            //window.location.reload();
        }
	  
	} catch (error) {
		console.error('Error In Save Data :', error);
	}
}
export const nxtdash_install_plugin = async (e, args, slug, setNxtOtherPluginInstall, nav) => {
    
    let loaderclass = 'nxt-white-loader';
    if(nav == 'more_products'){
        loaderclass = 'nxt-blue-loader';
    }else if(slug == 'uichemy'){
        loaderclass = 'nxt-black-loader';
    }
    e.target.innerHTML = `<span class="nxtext-loading-circle ${loaderclass}"></span>`;
    
	try {
		const response = await nxtdash_fetch_api(args),
        data = await response;
    
        if (data) {     
            if(nav == 'welcome'){
                e.target.innerHTML = 'Installed';
                window.location.reload();
            }else{
                setNxtOtherPluginInstall((prevState) => ({
                    ...prevState,
                    [slug]: {
                        ...prevState[slug],
                        install: true,
                        active: false,
                    },
                }));
            }
        }
	  
	} catch (error) {
		console.error('Error In Save Data :', error);
	}
}

export const nxtInstallCall = async (e, reload = true, slug="" ,setInstalled = '') => {
    let ajxData = new FormData(),
        formData = {};

    Object.assign(formData, {
        action: 'nexter_ext_plugin_install',
        slug : slug,
        nexter_nonce: nxtext_ajax_object.ajax_nonce,
    });
    appendFormData(ajxData, formData);
    if(slug=='wdesignkit' && nxtext_ajax_object?.dashData?.wdkactive != '1'){
        e.target.innerHTML = 'Installing WDesignKit';
    }else if(slug=='wdesignkit' && nxtext_ajax_object?.dashData?.wdkactive == '1'){
        e.target.innerHTML = 'Activating WDesignKit';
    }else if(slug=='the-plus-addons-for-block-editor' && nxtext_ajax_object?.dashData?.tpgbactivate != '1'){
        e.target.innerHTML = 'Installing Nexter Blocks';
    }else if(slug=='the-plus-addons-for-block-editor' && nxtext_ajax_object?.dashData?.tpgbactivate == '1'){
        e.target.innerHTML = 'Activating Nexter Blocks';
    }else if(slug=='nexter-extension' && nxtext_ajax_object?.dashData?.extensionactivate != '1'){
        e.target.innerHTML = 'Installing Nexter Extension';
    }else if(slug=='nexter-extension' && nxtext_ajax_object?.dashData?.extensionactivate == '1'){
        e.target.innerHTML = 'Activating Nexter Extension';
    }
    
    try {
        const response = await nxtdash_fetch_api(ajxData);
        const data = await response;

        if (data) {
            setTimeout(() => {
                if(slug=='wdesignkit'){
                    e.target.innerHTML = 'Import Templates';
                }else if(slug=='the-plus-addons-for-block-editor'){
                    e.target.innerHTML = 'Activated Blocks';
                }else if(slug=='nexter-extension'){
                    e.target.innerHTML = 'Activated Extensions';
                }
            }, 2000);
            if(slug=='wdesignkit'){
                nxtext_ajax_object.dashData.wdadded= data.Success;

                if (typeof setInstalled === 'function') {
                    setInstalled(true);
                    nxtext_ajax_object.dashData.wdadded= data.Success;
                }
            }else if(slug=='the-plus-addons-for-block-editor'){
                nxtext_ajax_object.dashData.tpgbinstall = data.Success;
            }else if(slug=='nexter-extension'){
                nxtext_ajax_object.dashData.extensioninstall = data.Success;
            }
            
            if(reload){
                window.location.reload();
            }
            
        }
    } catch (error) {
        console.error('Error in Cache :', error);
    }
}

// Save Data 
export const nxtdash_save_data = async (e,args, callfun = '') => {    
	e.target.innerHTML = 'Saving...';

    let saveArgs = args;
    if (args.action && (args.action === 'tpgb_blocks_opts_save' || args.action === 'tpgb_custom_css_js_save' || args.action === 'tpgb_connection_data_save' || args.action === 'tpgb_white_label_save')) {
        saveArgs = new FormData();
	    appendFormData(saveArgs, args);
    }

	try {
		const response = await nxtdash_fetch_api(saveArgs),
        data = await response;
    
        if (data) {   
            
            if (args.action && args.action === 'tpgb_blocks_opts_save') {
                const enableNormalBlocks = JSON.parse(args.enable_normal_blocks || '{}');
                const tpExtraOption = JSON.parse(args.tp_extra_option || '{}');
        
                if (!nxtext_ajax_object.dashData || !Array.isArray(nxtext_ajax_object.dashData.enableBlock)) {
                    nxtext_ajax_object.dashData = nxtext_ajax_object.dashData || {};
                    nxtext_ajax_object.dashData.enableBlock = [];
                }
                
                nxtext_ajax_object.dashData.avtiveBlock = enableNormalBlocks.length
                nxtext_ajax_object.dashData.enableBlock = Array.from(
                    new Set([...enableNormalBlocks, ...tpExtraOption])
                );
        
            } else if (args.action && args.action === 'tpgb_connection_data_save') {
                const newData = JSON.parse(args.tpgb_connection_data || '{}');
        
                if (!Array.isArray(nxtext_ajax_object.dashData.extOption)) {
                    nxtext_ajax_object.dashData.extOption = [{}];
                }
        
                const existingData = nxtext_ajax_object.dashData.extOption || {};
                const updatedData = { ...existingData, ...newData };
        
                nxtext_ajax_object.dashData.extOption = updatedData;
            }else if (args.action && args.action === 'tpgb_custom_css_js_save') {
                const ctmCss = args.tpgb_custom_css_editor;
                const ctmJs = args.tpgb_custom_js_editor;

                if (!nxtext_ajax_object.dashData.customCode) {
                    nxtext_ajax_object.dashData.customCode = {};
                }
                nxtext_ajax_object.dashData.customCode.tpgb_custom_css_editor = ctmCss;
                nxtext_ajax_object.dashData.customCode.tpgb_custom_js_editor = ctmJs;
                
            }else if (args.action && args.action === 'tpgb_white_label_save') {
                const whfield = args.fields;

                nxtext_ajax_object.dashData.whiteLabel = whfield
            }
            
            e.target.innerHTML = 'Done';
            if(callfun  && typeof callfun === "function"){
                setTimeout(callfun, 500)
            }

            setTimeout(() => {
                e.target.innerHTML = 'Save';
            }, 2000);
        }
	  
	} catch (error) {
		console.error('Error In Save Data :', error);
	}
}

