export const extraOptionsSave = async (evt, key, opt) =>{
    let action_ajax = '', active_deactive = '';
    if(evt.target.checked == true){
        action_ajax = 'nexter_extra_ext_active';
        active_deactive = 'active';
    }else{
        action_ajax = 'nexter_extra_ext_deactivate';
        active_deactive = 'deactive';
    }

    const formData = new FormData();
    formData.append('action', action_ajax);
    formData.append('extension_type', key);
    formData.append('active_deactive', active_deactive); 
    formData.append('nexter_nonce', nxtext_ajax_object.ajax_nonce); 
    nxtdash_fetch_api(formData)
}

export const nxtReplaceBtnClick = async (e,args, setOpt, type) => {
    let popWrap = e.target.closest('.nxtext_settings_popup');
    let getMainW = popWrap.querySelector('.nxtext_field_card_cover');
    let getHead = popWrap.querySelector('.nxtext_popup_heading')
    
	try {
		const response = await nxtdash_fetch_api(args),
        data = await response;
        if(data && getMainW && getHead){
            let getID = getMainW.getAttribute('id');
            if(getID == 'wp-replace-url'){
                getHead.insertAdjacentHTML('beforeend',replaceAlertMessage(data, type));
                if(data.data && data.data.result && data.data.result > 0){
                    if(type == 'replace'){
                        setOpt(true);
                    }
                }else{
                    if(type == 'replace'){
                        setOpt(false);
                    }
                }
                let toast = getHead.querySelector('.nxtext_toast_msg');
                if(toast){
                    setTimeout(()=>{
                        toast.classList.add('active')
                    }, 50)
                    setTimeout(()=>{
                        toast.classList.remove('active')
                    }, 2500)
                    setTimeout(()=>{
                        toast.remove()
                    }, 3000)
                }
            }        
        }
	} catch (error) {
		console.error('Error In Save Data :', error);
	}
}
