export const nxtAdobeFontGet = async (e,args, setOpt, setOptSetting) => {
    e.target.innerHTML = 'Checking...';
    let popWrap = e.target.closest('.nxtext_settings_popup');
    let getMainW = popWrap.querySelector('.nxtext_field_card_cover');
    
	try {
		const response = await nxtdash_fetch_api(args),
        data = await response;
        if(data && getMainW){
            let getID = getMainW.getAttribute('id');
            if(data.data && data.data.settings){
                const updatedSettings = { ...setOpt };
                updatedSettings[getID].values = data.data.settings;
                setOptSetting(updatedSettings);           
            }else{
                getMainW.insertAdjacentHTML('beforeend',adobeAlertMessage());
                let toast = getMainW.querySelector('.nxtext_toast_msg');
                if(toast){
                    setTimeout(()=>{
                        toast.classList.add('active')
                    }, 50)
                    setTimeout(()=>{
                        toast.classList.remove('active')
                    }, 2500)
                    setTimeout(()=>{
                        toast.remove()
                    }, 3000)
                }
            }
            e.target.innerHTML = 'Done';
            setTimeout(() => {
                e.target.innerHTML = 'Save';
            }, 2000);
        }
	} catch (error) {
		console.error('Error In Save Data :', error);
	}
}

export const nxtRegenerateThumb = async (e, args, nonce, imageSize) => {
    e.target.innerHTML = 'Regenerating...';
    var regenerated_images_count = 0;
    try {
		const response = await nxtdash_fetch_api(args),
        data = await response;
        if(data && data.success && data?.data?.content?.attachment_ids){
            var attachment_ids = data?.data?.content?.attachment_ids || 0;
            if( attachment_ids.length != 0 ){
                e.target.innerHTML = 'Waiting for server to regenerate ' + attachment_ids.length + ' 	Images' ;
                setTimeout(function(){
                    if(attachment_ids.length < regenerated_images_count){
                        e.target.innerHTML = 'Hold On ' + attachment_ids.length + 'already regenerated'
                    }
                }, 1000);
                attachment_ids.forEach(function (attachment_id){
                    const formData = new FormData();
                    formData.append('action', 'nexter_regenerate_image_thumbnail_by_id');
                    formData.append('thumbnail_id', attachment_id);
                    formData.append('image_sizes_to_be_generated', imageSize);
                    formData.append('nexter_nonce', nonce);

                    const response2 = nxtdash_fetch_api(formData),
                    data2 = response2;

                    if(data2 && data2.success){
                        setTimeout(function(){
                            e.target.innerHTML = 'It will take few seconds to regenerate';
                        }, 3000);
                        regenerated_images_count++;
                        if((attachment_ids.length / 2 ) < regenerated_images_count ) {
                            e.target.innerHTML = 'About to complete';
                        }
                    }
                })
            }
        }
	} catch (error) {
		console.error('Error In Save Data :', error);
	}  
}


